// ── Code: Sanitize ──────────────────────────────────────────────────────────
// CLAUDE.md Pattern 1: accept both body and root-level input (n8n wraps differently
// depending on whether the trigger is a webhook or HTTP Request node).
// CLAUDE.md Pattern 4: JWT travels in body.jwt — never as Authorization header.
const input = ($input.first().json.body) ? $input.first().json.body : $input.first().json;

const amount = parseFloat(input.amount);
if (isNaN(amount) || amount <= 0) throw new Error('Payment amount must be positive');
if (amount > 100000)               throw new Error('Amount exceeds maximum £100,000');
if (!input.booking_id)             throw new Error('Missing booking_id');
if (!input.customer_id && input.payment_method !== 'stripe') {
  // customer_id is optional for Stripe path — webhook already recorded it
  // For manual path it is required for the DB call
}

// Payment type
const sentType   = (input.payment_type || '').toLowerCase();
const payment_type = (sentType === 'deposit') ? 'deposit' : 'balance';

const balance    = parseFloat(input.balance_due || 999999);
const is_partial = payment_type === 'balance' && amount < (balance - 0.005);

// Reference number
const ts  = new Date();
const pad = n => String(n).padStart(2,'0');
const stamp = ts.getFullYear() + pad(ts.getMonth()+1) + pad(ts.getDate()) +
              pad(ts.getHours()) + pad(ts.getMinutes()) + pad(ts.getSeconds());
const rand   = Math.random().toString(36).slice(2,6).toUpperCase();
const prefix = payment_type === 'deposit' ? 'DEP' : (input.payment_method === 'stripe' ? 'STR' : 'REF');
const reference_number = prefix + '-' + stamp + '-' + rand;

// Payment method — default to 'cash' for manual path if not supplied
const payment_method = (input.payment_method || 'cash').toLowerCase();

// BACS bank details — frontend sends these from GET /stripe/config
const bacs_account_name   = input.bacs_account_name   || '';
const bacs_sort_code      = input.bacs_sort_code      || '';
const bacs_account_number = input.bacs_account_number || '';

return {
  json: {
    ...input,
    tenant_id: parseInt(
      input.tenant_id ||
      $input.first().json.headers?.['x-tenant-id'] ||
      $input.first().json.query?.tenant_id ||
      '0'
    ),
    amount,
    payment_type,
    is_partial,
    reference_number,
    payment_method,
    bacs_account_name,
    bacs_sort_code,
    bacs_account_number,
    deposit_reference: input.deposit_reference || null,
    jwt: String(input.jwt || '').trim()
  }
};

// ── Code: Build Stripe Email ─────────────────────────────────────────────────
// Stripe path: payment is already recorded by the db-api webhook handler.
// This node only builds the confirmation email.
const s = $('Code: Sanitize').first().json;

const fmt     = n => '£' + parseFloat(n || 0).toFixed(2);
const fmtDate = d => {
  if (!d) return '—';
  const dt = new Date(String(d).slice(0,10) + 'T00:00:00');
  return dt.toLocaleDateString('en-GB', { weekday:'long', day:'numeric', month:'long', year:'numeric' });
};
const fmtTime = t => t ? String(t).slice(0,5) : '—';

const customer_email = s.customer_email || s.email || '';
const customer_name  = s.customer_name  || s.full_name || 'Valued Customer';
const amount         = parseFloat(s.amount || 0);
const ref            = s.reference_number || s.stripe_session_id || '—';
const room           = s.room_name   || '—';
const eventDate      = s.event_date  || s.date_from || null;
const startTime      = s.start_time  || null;
const endTime        = s.end_time    || null;

const subject = `Card Payment Confirmed ✓ — ${fmtDate(eventDate)} | Ref: ${ref}`;

const html = `<!DOCTYPE html>
<html><head><meta charset="UTF-8"><meta name="viewport" content="width=device-width,initial-scale=1.0"></head>
<body style="margin:0;padding:0;background:#f8fafc;font-family:-apple-system,BlinkMacSystemFont,'Segoe UI',Roboto,sans-serif;">
  <div style="max-width:600px;margin:0 auto;padding:32px 16px;">
    <div style="background:#10b981;border-radius:12px 12px 0 0;padding:32px;text-align:center;">
      <p style="margin:0 0 6px;color:rgba(255,255,255,0.8);font-size:12px;letter-spacing:1.5px;text-transform:uppercase;">VenueDesk Booking System</p>
      <h1 style="margin:0;color:#ffffff;font-size:22px;font-weight:700;">Card Payment Confirmed ✓</h1>
    </div>
    <div style="background:#ffffff;border:1px solid #e2e8f0;border-top:none;border-radius:0 0 12px 12px;padding:32px;">
      <div style="text-align:center;margin-bottom:24px;">
        <span style="display:inline-block;background:#ecfdf5;color:#065f46;font-size:11px;font-weight:700;letter-spacing:1.5px;padding:6px 18px;border-radius:20px;">PAYMENT RECEIVED VIA CARD</span>
      </div>
      <p style="margin:0 0 16px;color:#1e293b;font-size:15px;">Dear <strong>${customer_name}</strong>,</p>
      <p style="margin:0 0 24px;color:#374151;font-size:15px;line-height:1.7;">Thank you — your card payment of <strong>${fmt(amount)}</strong> has been received and your booking is now <strong>confirmed</strong>.</p>
      <div style="background:#f8fafc;border:1px solid #e2e8f0;border-radius:8px;padding:20px;margin-bottom:16px;">
        <p style="margin:0 0 14px;color:#0f172a;font-size:12px;font-weight:700;text-transform:uppercase;letter-spacing:0.8px;">Booking Details</p>
        <table style="width:100%;border-collapse:collapse;font-size:14px;">
          <tr><td style="padding:5px 0;color:#64748b;">Room / Venue</td><td style="padding:5px 0;color:#1e293b;font-weight:600;">${room}</td></tr>
          <tr><td style="padding:5px 0;color:#64748b;">Event Date</td><td style="padding:5px 0;color:#1e293b;font-weight:600;">${fmtDate(eventDate)}</td></tr>
          <tr><td style="padding:5px 0;color:#64748b;">Time</td><td style="padding:5px 0;color:#1e293b;font-weight:600;">${fmtTime(startTime)} – ${fmtTime(endTime)}</td></tr>
        </table>
      </div>
      <div style="background:#eef2ff;border-radius:8px;padding:14px 20px;margin-bottom:28px;text-align:center;">
        <p style="margin:0;color:#64748b;font-size:12px;">Payment Reference</p>
        <p style="margin:4px 0 0;color:#4f46e5;font-size:17px;font-weight:700;letter-spacing:0.5px;">${ref}</p>
      </div>
      <p style="margin:0;color:#64748b;font-size:13px;line-height:1.6;">Please keep this email as your payment receipt. Questions? Reply quoting your reference or contact <a href="mailto:bookings@venuedesk.co.uk" style="color:#6366f1;">bookings@venuedesk.co.uk</a>.</p>
    </div>
    <div style="text-align:center;padding:20px 0 0;">
      <p style="margin:0;color:#94a3b8;font-size:11px;">Automated message from VenueDesk Booking System.</p>
    </div>
  </div>
</body></html>`;

return { json: { ...s, subject, html, email: customer_email } };

// ── Code: Build Email Content (Manual / BACS paths) ─────────────────────────
// Handles: cash, bank_transfer, bacs, cheque, card (non-Stripe), and all
// other payment_method values.
// For BACS specifically: renders an 'Awaiting Payment' template with bank details.

const sanitize    = $('Code: Sanitize').first().json;
const paymentNode = $('DB: Record Payment').first().json;
const paymentData = paymentNode?.success ? (paymentNode.data ?? paymentNode) : {};
const detailsRaw  = ($json.success !== false) ? ($json.data ?? $json) : {};
const webhookData = sanitize;

const raw = { ...webhookData, ...paymentData, ...detailsRaw };

const customer = {
  ...raw,
  email:     raw.customer_email || raw.email     || sanitize.email     || '',
  full_name: raw.customer_name  || raw.full_name || 'Valued Customer',
  event_date: raw.event_date    || raw.date_from || raw.booking_date   || null,
};

const payment_method = (sanitize.payment_method || 'cash').toLowerCase();
const payment_type   = sanitize.payment_type;
const is_partial     = sanitize.is_partial;
const amount         = parseFloat(sanitize.amount || 0);
const ref            = sanitize.reference_number || '—';
const remaining      = parseFloat(raw.balance_due ?? raw.new_balance ?? 0);
const total          = parseFloat(customer.total_amount || 0);
const booking_id     = sanitize.booking_id || '—';

// BACS bank details — sent by frontend from GET /stripe/config, or from tenant config
const bacs_account_name   = sanitize.bacs_account_name   || '';
const bacs_sort_code      = sanitize.bacs_sort_code       || '';
const bacs_account_number = sanitize.bacs_account_number  || '';
const isBacs = payment_method === 'bacs' || payment_method === 'bank_transfer';

const fmt = n => '£' + parseFloat(n || 0).toFixed(2);
const fmtDate = d => {
  if (!d) return '—';
  const dt = new Date(String(d).slice(0,10) + 'T00:00:00');
  return dt.toLocaleDateString('en-GB', { weekday:'long', day:'numeric', month:'long', year:'numeric' });
};
const fmtTime = t => t ? String(t).slice(0,5) : '—';

let subject, headingColour, headingText, statusBadge, bodyText, extraSection = '';

if (isBacs) {
  // ── BACS / Awaiting Payment template ─────────────────────────────────────
  subject       = `Booking Reserved — Awaiting BACS Payment | Ref: ${booking_id}`;
  headingColour = '#f59e0b';
  headingText   = 'Booking Reserved — Payment Pending';
  statusBadge   = { text:'AWAITING PAYMENT', bg:'#fffbeb', color:'#b45309' };
  bodyText      = `Your booking for <strong>${customer.room_name || 'your venue'}</strong> has been reserved. Please transfer the full amount to complete your booking.`;

  // Inject BACS bank details if available
  if (bacs_sort_code || bacs_account_number) {
    extraSection = `
      <div style="background:#fffbeb;border:2px solid #f59e0b;border-radius:8px;padding:20px;margin-bottom:16px;">
        <p style="margin:0 0 14px;color:#92400e;font-size:12px;font-weight:700;text-transform:uppercase;letter-spacing:0.8px;">Bank Transfer Details</p>
        <table style="width:100%;border-collapse:collapse;font-size:14px;">
          ${bacs_account_name   ? `<tr><td style="padding:5px 0;color:#64748b;width:45%;">Account Name</td><td style="padding:5px 0;color:#1e293b;font-weight:600;">${bacs_account_name}</td></tr>` : ''}
          ${bacs_sort_code      ? `<tr><td style="padding:5px 0;color:#64748b;">Sort Code</td><td style="padding:5px 0;color:#1e293b;font-weight:600;font-family:monospace;">${bacs_sort_code}</td></tr>` : ''}
          ${bacs_account_number ? `<tr><td style="padding:5px 0;color:#64748b;">Account Number</td><td style="padding:5px 0;color:#1e293b;font-weight:600;font-family:monospace;">${bacs_account_number}</td></tr>` : ''}
          <tr style="border-top:1px solid #f59e0b;"><td style="padding:8px 0 5px;color:#64748b;">Payment Reference</td><td style="padding:8px 0 5px;color:#d97706;font-weight:700;font-family:monospace;">${booking_id}</td></tr>
          <tr><td style="padding:5px 0;color:#64748b;">Amount Due</td><td style="padding:5px 0;color:#d97706;font-weight:700;">${fmt(amount)}</td></tr>
        </table>
        <p style="margin:14px 0 0;color:#92400e;font-size:12px;">⚠️ Please use your Booking ID as the payment reference so we can match your transfer.</p>
      </div>`;
  }
} else if (payment_type === 'deposit') {
  subject       = `Deposit Payment Confirmed — ${fmtDate(customer.event_date)} | Ref: ${ref}`;
  headingColour = '#6366f1';
  headingText   = 'Deposit Payment Confirmed';
  statusBadge   = { text:'DEPOSIT RECEIVED', bg:'#eef2ff', color:'#4f46e5' };
  bodyText      = `Thank you for your deposit payment of <strong>${fmt(amount)}</strong>. Your booking for <strong>${customer.room_name || 'your venue'}</strong> is now secured.`;
} else if (is_partial) {
  subject       = `Payment Received — Remaining Balance: ${fmt(remaining)} | Ref: ${ref}`;
  headingColour = '#f59e0b';
  headingText   = 'Partial Balance Payment Received';
  statusBadge   = { text:'PAYMENT RECEIVED', bg:'#fffbeb', color:'#b45309' };
  bodyText      = `Thank you for your payment of <strong>${fmt(amount)}</strong>. Your remaining balance of <strong>${fmt(remaining)}</strong> is due before your event date.`;
} else {
  subject       = `Balance Fully Settled — Booking Confirmed ✓ | Ref: ${ref}`;
  headingColour = '#10b981';
  headingText   = 'Balance Fully Settled ✓';
  statusBadge   = { text:'FULLY PAID', bg:'#ecfdf5', color:'#065f46' };
  bodyText      = `Thank you for your final payment of <strong>${fmt(amount)}</strong>. Your booking balance is now <strong>fully settled</strong> — we look forward to hosting your event!`;
}

const remainingRow = (!isBacs && remaining > 0)
  ? `<tr style="border-top:1px solid #e2e8f0;"><td style="padding:8px 0 5px;color:#64748b;">Balance Remaining</td><td style="padding:8px 0 5px;color:#f59e0b;font-weight:700;text-align:right;">${fmt(remaining)}</td></tr>`
  : (!isBacs ? `<tr style="border-top:1px solid #e2e8f0;"><td style="padding:8px 0 5px;color:#64748b;">Balance Remaining</td><td style="padding:8px 0 5px;color:#10b981;font-weight:700;text-align:right;">£0.00 — Fully Paid ✓</td></tr>` : '');

const html = `<!DOCTYPE html>
<html><head><meta charset="UTF-8"><meta name="viewport" content="width=device-width,initial-scale=1.0"></head>
<body style="margin:0;padding:0;background:#f8fafc;font-family:-apple-system,BlinkMacSystemFont,'Segoe UI',Roboto,sans-serif;">
  <div style="max-width:600px;margin:0 auto;padding:32px 16px;">
    <div style="background:${headingColour};border-radius:12px 12px 0 0;padding:32px;text-align:center;">
      <p style="margin:0 0 6px;color:rgba(255,255,255,0.8);font-size:12px;letter-spacing:1.5px;text-transform:uppercase;">VenueDesk Booking System</p>
      <h1 style="margin:0;color:#ffffff;font-size:22px;font-weight:700;line-height:1.3;">${headingText}</h1>
    </div>
    <div style="background:#ffffff;border:1px solid #e2e8f0;border-top:none;border-radius:0 0 12px 12px;padding:32px;">
      <div style="text-align:center;margin-bottom:24px;">
        <span style="display:inline-block;background:${statusBadge.bg};color:${statusBadge.color};font-size:11px;font-weight:700;letter-spacing:1.5px;padding:6px 18px;border-radius:20px;">${statusBadge.text}</span>
      </div>
      <p style="margin:0 0 16px;color:#1e293b;font-size:15px;">Dear <strong>${customer.full_name || 'Valued Customer'}</strong>,</p>
      <p style="margin:0 0 24px;color:#374151;font-size:15px;line-height:1.7;">${bodyText}</p>
      ${extraSection}
      <div style="background:#f8fafc;border:1px solid #e2e8f0;border-radius:8px;padding:20px;margin-bottom:16px;">
        <p style="margin:0 0 14px;color:#0f172a;font-size:12px;font-weight:700;text-transform:uppercase;letter-spacing:0.8px;">Booking Details</p>
        <table style="width:100%;border-collapse:collapse;font-size:14px;">
          <tr><td style="padding:5px 0;color:#64748b;width:45%;">Room / Venue</td><td style="padding:5px 0;color:#1e293b;font-weight:600;">${customer.room_name || '—'}</td></tr>
          <tr><td style="padding:5px 0;color:#64748b;">Event Date</td><td style="padding:5px 0;color:#1e293b;font-weight:600;">${fmtDate(customer.event_date)}</td></tr>
          <tr><td style="padding:5px 0;color:#64748b;">Time</td><td style="padding:5px 0;color:#1e293b;font-weight:600;">${fmtTime(customer.start_time)} – ${fmtTime(customer.end_time)}</td></tr>
        </table>
      </div>
      ${!isBacs ? `<div style="background:#f8fafc;border:1px solid #e2e8f0;border-radius:8px;padding:20px;margin-bottom:24px;">
        <p style="margin:0 0 14px;color:#0f172a;font-size:12px;font-weight:700;text-transform:uppercase;letter-spacing:0.8px;">Payment Summary</p>
        <table style="width:100%;border-collapse:collapse;font-size:14px;">
          <tr><td style="padding:5px 0;color:#64748b;">Total Booking Value</td><td style="padding:5px 0;color:#1e293b;text-align:right;">${fmt(total)}</td></tr>
          <tr><td style="padding:5px 0;color:#64748b;">Amount Paid (This Transaction)</td><td style="padding:5px 0;color:${headingColour};font-weight:700;text-align:right;">${fmt(amount)}</td></tr>
          ${remainingRow}
        </table>
      </div>` : ''}
      <div style="background:#eef2ff;border-radius:8px;padding:14px 20px;margin-bottom:28px;text-align:center;">
        <p style="margin:0;color:#64748b;font-size:12px;">${isBacs ? 'Booking Reference (use as payment ref)' : 'Payment Reference'}</p>
        <p style="margin:4px 0 0;color:#4f46e5;font-size:17px;font-weight:700;letter-spacing:0.5px;">${isBacs ? booking_id : ref}</p>
      </div>
      <p style="margin:0;color:#64748b;font-size:13px;line-height:1.6;">Please keep this email for your records. Questions? Contact <a href="mailto:bookings@venuedesk.co.uk" style="color:#6366f1;text-decoration:none;">bookings@venuedesk.co.uk</a>.</p>
    </div>
    <div style="text-align:center;padding:20px 0 0;">
      <p style="margin:0;color:#94a3b8;font-size:11px;">Automated message from VenueDesk Booking System. Please do not reply directly.</p>
    </div>
  </div>
</body></html>`;

return { json: { ...customer, subject, html, email: customer.email } };
